  -ex 'continue' -ex 'printf "STOP pc=%p\n",$pc' -ex 'continue' -ex 'printf "STOP pc=%p\n",$pc' -ex 'continue' -ex 'printf "STOP pc=%p\n",$pc' \
  2>&1 | grep -iv "warning\|New Thread\|Thread 0x\|Thread deb\|host libth" | grep -iE "candidate|patched|STOP pc|0x40deac|0x40b2fc|0x40a618|0x457c00|exited|SIGSEGV" | head"}

